import argparse,json
from pathlib import Path
def main():
 p=argparse.ArgumentParser();p.add_argument('--scene',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
 s=json.loads(a.scene.read_text()); data=json.dumps(s)
 three=Path('outputs/re3sim-trial/viewer-assets/three.js').read_text()
 js='''const S=__DATA__;const scene=new THREE.Scene();scene.background=new THREE.Color(0x18222b);const cam=new THREE.PerspectiveCamera(70,innerWidth/innerHeight,.03,100);cam.position.set(0,1.5,0);const ren=new THREE.WebGLRenderer({antialias:true});ren.setSize(innerWidth,innerHeight);document.body.appendChild(ren.domElement);scene.add(new THREE.HemisphereLight(0xffffff,0x334455,2));function mat(c){return new THREE.MeshStandardMaterial({color:c,roughness:.8,side:THREE.DoubleSide})}function box(x,y,z,s,c){let m=new THREE.Mesh(new THREE.BoxGeometry(...s),mat(c));m.position.set(x,z,y);scene.add(m)}const w=S.width,l=S.length,h=S.height;box(0,l/2,h/2,[w,.05,h],0xcfcfcf);box(0,-l/2,h/2,[w,.05,h],0xcfcfcf);box(w/2,0,h/2,[.05,l,h],0xd0c0c0);box(-w/2,0,h/2,[.05,l,h],0xd0c0c0);box(0,0,-.03,[w,l,.05],0xbfc5d0);box(0,0,h,[w,l,.05],0x555555);for(const f of S.furniture)box(f.center[0],f.center[1],f.size[2]/2,f.size,f.color.map(x=>Math.round(x*255)).reduce((a,x)=>a*256+x,0));let keys={};onkeydown=e=>keys[e.code]=1;onkeyup=e=>keys[e.code]=0;let yaw=0,pitch=0,drag=0,lx=0,ly=0;onpointerdown=e=>{drag=1;lx=e.clientX;ly=e.clientY};onpointerup=()=>drag=0;onpointermove=e=>{if(!drag)return;yaw-=(e.clientX-lx)*.004;pitch=Math.max(-1.4,Math.min(1.4,pitch-(e.clientY-ly)*.004));lx=e.clientX;ly=e.clientY};function go(){let v=new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw));let r=new THREE.Vector3(v.z,0,-v.x);if(keys.KeyW)cam.position.addScaledVector(v,.04);if(keys.KeyS)cam.position.addScaledVector(v,-.04);if(keys.KeyA)cam.position.addScaledVector(r,-.04);if(keys.KeyD)cam.position.addScaledVector(r,.04);cam.position.x=Math.max(-w/2+.15,Math.min(w/2-.15,cam.position.x));cam.position.z=Math.max(-l/2+.15,Math.min(l/2-.15,cam.position.z));cam.rotation.set(pitch,yaw,0,'YXZ')}function f(){requestAnimationFrame(f);go();ren.render(scene,cam)}f();onresize=()=>{ren.setSize(innerWidth,innerHeight);cam.aspect=innerWidth/innerHeight;cam.updateProjectionMatrix()};'''.replace('__DATA__',data)
 html='<!doctype html><meta charset=utf-8><title>Simulator ground truth walkthrough</title><style>body{margin:0;overflow:hidden}#i{position:fixed;z-index:2;color:white;background:#203040dd;padding:12px;font:14px system-ui}</style><div id=i>Simulator ground truth · WASD move · drag to look</div><script>'+three+'</script><script>'+js+'</script>'
 a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(html)
if __name__=='__main__':main()
